              console.log('Raw types:', types);
            }}
          >
            {t('retry_button')}
          </Button>
        </View>
      </ScrollView>
    );
  }

  return (
    <ScrollView>
      <KeyboardAvoidingView behavior={Platform.OS === 'ios' ? 'padding' : null}>
